tasks.answer:
def stairs(n):                   # 한 번에 1칸 또는 2칸
    if n == 1:
        return 1
    elif n == 2:
        return 2
    return stairs(n - 1) + stairs(n - 2)

for n in range(1, 7):
    print(f'{n}칸: {stairs(n)}가지')
